60	import { StudioTopBar } from "./StudioTopBar";
61	
62	const INITIAL_STATE: BuilderState = {
63	  questions: [],
64	  selectedId: null,
65	  dirty: false,
66	};
67	
68	/**
69	 * The WYSIWYG questionnaire builder: left outline, live canvas rendered by
70	 * the full renderer (form/), right inspector. Replaces the old
71	 * QuestionnaireBuilderPage on the same routes and keeps its contracts: all
72	 * edit state in builderReducer, `?mode=preview` / `?import=1` params, the
73	 * dirty-guarded re-seed, save through `buildUpdateBody` as one full PUT —
74	 * now including the questionnaire metadata edited in Form settings.
75	 */
76	export function QuestionnaireStudioPage({
77	  scope,
78	  id,
79	}: {
80	  scope: QuestionnaireScope;
81	  id: string;
82	}) {
83	  const { t } = useTranslation();
84	
85	  const {
86	    data: questionnaire,
87	    isLoading,
88	    isError,
89	  } = useQuery({
90	    queryKey: questionnaireKeys.detail(id),
91	    queryFn: query(questionnaireApi.get, { pathParams: { id } }),
92	  });
93	
94	  const [state, dispatch] = useReducer(builderReducer, INITIAL_STATE);
95	
96	  useEffect(() => {
97	    // Skip while the user has unsaved edits (`state.dirty`) — otherwise a
98	    // background refetch that returns a new `questionnaire` reference (e.g.
99	    // refetchOnReconnect after a network blip) would silently discard them.
100	    // The post-save path resets explicitly (see the mutation's onSuccess
101	    // below) after dirty has already been cleared, so this guard doesn't
102	    // block that path. The metadata form protects itself the same way via
103	    // its `values` binding + `keepDirtyValues`.
104	    if (questionnaire && !state.dirty) {
105	      dispatch({
106	        type: "reset",
107	        questions: questionnaire.questions,
108	        keepSelectedId: state.selectedId,
109	      });
110	    }
111	    // eslint-disable-next-line react-hooks/exhaustive-deps
112	  }, [questionnaire]);
113	
114	  const metaSchema = useMemo(() => questionnaireBasicSchema(t), [t]);
115	  const form = useForm<DetailFormValues>({
116	    resolver: zodResolver(metaSchema),
117	    values: questionnaire
118	      ? {
119	          title: questionnaire.title,
120	          slug: questionnaire.slug,
121	          description: questionnaire.description ?? "",
122	          status: questionnaire.status,
123	        }
124	      : undefined,
125	    resetOptions: { keepDirtyValues: true },
126	  });
127	
128	  const [queryParams, setQueryParams] = useQueryParams();
129	  const { mode, import: importParam } = queryParams;
130	  const [view, setView] = useState<"edit" | "preview">(
131	    mode === "preview" ? "preview" : "edit",
132	  );
133	  const [importOpen, setImportOpen] = useState(importParam === "1");
134	  const [inspectorTarget, setInspectorTarget] = useState<"form" | "question">(
135	    "question",
136	  );
137	  const [scrollRequest, setScrollRequest] = useState<{
138	    id: string;
139	    nonce: number;
140	  } | null>(null);
141	
142	  useEffect(() => {
143	    // The dialog's open state above already captured `?import=1` — strip it
144	    // from the URL (preserving any other params, e.g. `mode`) so a refresh
145	    // or Back navigation doesn't reopen the dialog.
146	    if (importParam !== "1") return;
147	    const { import: _import, ...rest } = queryParams;
148	    setQueryParams(rest, { overwrite: true, replace: true });
149	    // eslint-disable-next-line react-hooks/exhaustive-deps
150	  }, []);
151	
152	  const dirty = state.dirty || form.formState.isDirty;
153	  useNavigationPrompt(dirty, t("unsaved_changes_warning"));
154	
155	  const { canWrite, isLoading: isPermissionLoading } =
156	    useCanWriteQuestionnaire(scope);
157	
158	  // Creating or importing questions selects them in the reducer — the
159	  // inspector must follow, or it would stay on Form settings showing
160	  // nothing about the question that just appeared.
161	  const studioDispatch: typeof dispatch = (action) => {
162	    if (
163	      action.type === "addQuestion" ||
164	      action.type === "duplicateQuestion" ||
165	      action.type === "replaceAll"
166	    ) {
167	      setInspectorTarget("question");
168	    }
169	    dispatch(action);
170	  };
171	
172	  // Live draft for the canvas: a fresh identity per edit is exactly what
173	  // drives the form provider's live sync (it merges responses rather than
174	  // wiping them, so this is safe on every keystroke). Title/description
175	  // ride along from the metadata form so the canvas header is as realtime
176	  // as the questions.
177	  const [metaTitle, metaDescription] = useWatch({
178	    control: form.control,
179	    name: ["title", "description"],
180	  });
181	  const draft = useMemo(
182	    () =>
183	      questionnaire
184	        ? {
185	            ...questionnaire,
186	            title: metaTitle || questionnaire.title,
187	            description: metaDescription ?? questionnaire.description,
188	            questions: state.questions,
189	          }
190	        : undefined,
191	    [questionnaire, state.questions, metaTitle, metaDescription],
192	  );
193	
194	  const issues = useMemo(
195	    () => findInvalidQuestions(state.questions),
196	    [state.questions],
197	  );
198	  // First failing rule per question — powers the outline warning icons and
199	  // the canvas error chips alongside the top bar's popover.
200	  const issueKeysByQuestionId = useMemo(
201	    () =>
202	      new Map(
203	        issues.map(({ question, messageKey }) => [question.id, messageKey]),
204	      ),
205	    [issues],
206	  );
207	
208	  const { mutate: save, isPending } = useUpdateQuestionnaire(id, (updated) => {
